    if (paths.size != 1)
      fail(
        "SPINAL-PARAMETERIZED-VERILOG-STRUCTURAL-LEXICAL-PUBLICATION-MISMATCH",
        s"${owner.role} belongs to ${paths.size} published lexical blocks; exactly one is required",
        owner.sourceLocation
      )
